BEGIN;
CREATE TABLE IF NOT EXISTS marketing_email_templates(id SERIAL PRIMARY KEY,name VARCHAR(160) NOT NULL,category VARCHAR(80),status VARCHAR(20) NOT NULL DEFAULT 'draft' CHECK(status IN('draft','published','archived')),current_version INTEGER NOT NULL DEFAULT 1,created_by BIGINT REFERENCES users(id) ON DELETE SET NULL,created_at TIMESTAMP DEFAULT NOW(),updated_at TIMESTAMP DEFAULT NOW());
CREATE TABLE IF NOT EXISTS marketing_email_template_versions(id BIGSERIAL PRIMARY KEY,template_id INTEGER NOT NULL REFERENCES marketing_email_templates(id) ON DELETE CASCADE,version INTEGER NOT NULL,subject VARCHAR(255) NOT NULL,html_content TEXT NOT NULL,text_content TEXT NOT NULL,created_at TIMESTAMP DEFAULT NOW(),UNIQUE(template_id,version));
CREATE TABLE IF NOT EXISTS marketing_sender_profiles(id SERIAL PRIMARY KEY,name VARCHAR(120) NOT NULL,from_email VARCHAR(255) NOT NULL,reply_to VARCHAR(255),provider_type VARCHAR(30) NOT NULL DEFAULT 'graph',domain_config JSONB NOT NULL DEFAULT '{}',is_active BOOLEAN DEFAULT TRUE,created_at TIMESTAMP DEFAULT NOW());
CREATE TABLE IF NOT EXISTS marketing_email_messages(id BIGSERIAL PRIMARY KEY,template_version_id BIGINT REFERENCES marketing_email_template_versions(id) ON DELETE SET NULL,marketing_contact_id INTEGER REFERENCES marketing_contacts(id) ON DELETE SET NULL,sender_profile_id INTEGER REFERENCES marketing_sender_profiles(id) ON DELETE SET NULL,recipient_email VARCHAR(255) NOT NULL,subject TEXT NOT NULL,html_content TEXT NOT NULL,text_content TEXT NOT NULL,send_type VARCHAR(20) NOT NULL,tracking_token UUID NOT NULL UNIQUE,status VARCHAR(20) NOT NULL DEFAULT 'queued',scheduled_at TIMESTAMP,provider_message_id VARCHAR(255),last_error VARCHAR(500),created_at TIMESTAMP DEFAULT NOW(),sent_at TIMESTAMP);
CREATE TABLE IF NOT EXISTS marketing_email_delivery_events(id BIGSERIAL PRIMARY KEY,message_id BIGINT NOT NULL REFERENCES marketing_email_messages(id) ON DELETE CASCADE,event_type VARCHAR(20) NOT NULL,provider_event_id VARCHAR(255),metadata JSONB NOT NULL DEFAULT '{}',occurred_at TIMESTAMP DEFAULT NOW(),UNIQUE(provider_event_id));
CREATE TABLE IF NOT EXISTS marketing_subscription_types(id SERIAL PRIMARY KEY,code VARCHAR(50) UNIQUE NOT NULL,name VARCHAR(100) NOT NULL);
INSERT INTO marketing_subscription_types(code,name) VALUES('product_updates','Product Updates'),('promotions','Promotions'),('newsletters','Newsletters'),('events','Events'),('security_updates','Security Updates') ON CONFLICT(code) DO NOTHING;
CREATE TABLE IF NOT EXISTS marketing_subscriptions(marketing_contact_id INTEGER NOT NULL REFERENCES marketing_contacts(id) ON DELETE CASCADE,subscription_type_id INTEGER NOT NULL REFERENCES marketing_subscription_types(id) ON DELETE CASCADE,status VARCHAR(20) NOT NULL DEFAULT 'subscribed',updated_at TIMESTAMP DEFAULT NOW(),PRIMARY KEY(marketing_contact_id,subscription_type_id));
COMMIT;
